def cut_roads(cities, connections):
    # Build adjacency list
    graph = defaultdict(list)
    for i in range(1, cities + 1):
        graph[i] = []

    for edge in connections:
        node1 = min(edge[0], edge[1])
        node2 = max(edge[0], edge[1])
        graph[node1].append(node2)
        graph[node2].append(node1)

    visited = [False] * (cities + 1)
    partition1, partition2 = [i for i in range(1, cities + 1)], []
    queue = [(0, [1])]
    parent_costs = {}
    min_parents = []

    while queue:
        cost, current_partition = heapq.heappop(queue)
        for neighbor in graph[current_partition[-1]]:
            current_cost = cost + abs(current_partition[-1] - neighbor)
            if not visited[neighbor] and not neighbor in current_partition:
                heapq.heappush(queue, (current_cost, current_partition + [neighbor]))
                if len(current_partition) >= cities // 2:
                    visited[neighbor] = True
                    if len(current_partition) == cities // 2:
                        min_parents.append(parent_costs[neighbor])
                else:
                    visited[neighbor] = True
                    parent_costs[neighbor] = cost + abs(current_partition[-1] - neighbor)
                    min_parents.append(neighbor)
        if len(current_partition) == cities // 2:
            break

    # Restore partition1 to original partition1
    partition2 = [partition1[i] for i in range(cities // 2) if i not in partition2]
    partition1 = [partition1[i] for i in range(cities // 2) if i in partition2]

    # Clean up
