    for i in range(1, cities + 1):
        graph[i] = []

    for node1 in partition1:
        for node2 in partition2:
            cost = abs(node1 - node2)
            graph[node1].append(node2)
            graph[node2].append(node1)

    # Print remaining roads to be cut
    return min_parents
