            right_blocked = mid - 1
        else:
            left_blocked = mid + 1

    return pos if can_entrap(n, left_blocked, right_blocked, distances) else -1

def can_enttrap(n, left_room, right_room, distances, current_depth=-1):
    pos = 1 if distances[right_room - 1] else right_room

    for room in range(left_room, right_room):
        if room < right_room - 1:
            if right_room < len(distances) and current_depth + distances[right_room - 1] + 1 < distances[room + 1]:
                pos = max(position_right(room, right_room, distances, pos), pos)
        elif room == right_room - 1:
            next_room_distance = current_depth + distances[room]
            pos = max(position_right(room, right_room, distances, pos), pos)
            current_depth += next_room_distance
        elif right_room < len(distances) and next_room_distance + distances[right_room - 1] + 1 < distances[room + 1]:
            pos = max(position_right(room, right_room, distances, pos), pos)

    return left_room == pos <= right_room

def position_right(room, end_room, array, pos):
    if array[room] == 0:
        return end_room
    else:
        left_room_pos = position_right(room - 1, end_room, array, pos)
        if left_room_pos >= room:
            return max(room - 2, left_room_pos)
        if left_room_pos + 1 <= room:
            return min(pos, left_room_pos + 2)

