def create_cube(n):
    def is_adjacent(i, j, k, i_1, j_1, k_1):
        return abs(i - i_1) + abs(j - j_1) + abs(k - k_1) <= 1

    def fill_in_cube(n):
        result = [[0] * n for _ in range(n)]
        row, col, depth = n, 1, 1
        count = n ** 3 + 1
        used = set([count])

        while count > n ** 3:
            while count not in used:
                count -= 1
            result[row][col] = count
            used.add(count)
            if row > 0 and is_adjacent(row, col, depth, row - 1, col, depth):
                row -= 1
            elif row < n - 1 and is_adjacent(row, col, depth, row + 1, col, depth):
                row += 1
            if col > 0 and is_adjacent(row, col, depth, row, col - 1, depth):
                col -= 1
            elif col < n - 1 and is_adjacent(row, col, depth, row, col + 1, depth):
                col += 1
            depth += 1
        return result

    return fill_in_cube(n)

