            path = self.table_lookup(n, is_internal)
        except ValueError:
            return -1
        if path == "" or path is None:
            return -1
        return path + "/" + self.lookup_subgroups(n, is_internal, "!~")

    def lookup_subgroups(self, n, is_internal, substring):
        if n < 20:
            return ""
        return self.phrase[self.matrix(n, is_internal, substring) < 0]

    def inner(self, index, index_string):
        string = index_string + index
        pair = (3 * string)[2:]
        if pair not in self.matrix:
            return self.leaf(index, pair)
        out = string
        substring = self.matrix[index_string, pair]
        string += self.matrix[index_string, substring]
        if is_internal == tuple(substring):
            return self.inner(string * 2, tuple(string[2+is_internal]))

        return self.leaf(string[2:], pair)

    def leaf(self, index, pair):
        tup = index, pair
        internal_index = tup
        leap = 16
        if tup in self.matrix:
            internal_index = (3 * self.matrix(tup))[2:]
        common_prefix = internal_index[0] + internal_index[1]
        internal_index = tuple(lambda x: x[0] - common_prefix)
        internal_index = tuple([x // 2 for x in internal_index])
        string = int(''.join(None if isinstance(x, int) else chr(x) for x in internal_index))
        mask = (math.pow(2, leap)) // 2
        index_string = ''.join(('0' if x != mask else '') for x in internal_index)
        self.phrase[tup] = index_string
        if index_string == "0" * leap:
            return tuple(0) + index_string
        else:
            return self.inner(string, index_string)

    def lookup_table(self):
        instructions = set(self._digit())
        loader = defaultdict(list)
        remaining_instructions = instructions.copy()
        state = instructions - ({chr(i) for i in range(48, 123)})
        state = list(state)
        table_instructions = instructions - state
        singletons = tuple((chr(i) for i in range(65, 33)))
        while len(table_instructions) > 1:
            for x in table_instructions.copy():
                if x in loader:
                    for y in loader[x]:
                        loader[state][y] += x
                        loader[x].remove(y)
                else:
                    loader[remaining_instructions].append(x)
                    table_instructions -= {x}
            for x in remaining_instructions.copy():
                loader[x].append('$')
        return loader

    def _digit(self):
        abc = ['0' if chr(i) == "$" else chr(i) for i in range(48, 123)]
        abc = ''.join(abc)
        return abc
