import sys
from typing import List

def is_connectable(computer_list: List[int], connections: int) -> bool:
    """
    Check if it's possible to connect M or fewer devices through M-1 connections.
    """
    from itertools import combinations

    # Attempt to add a new connection between each existing pair of devices
    for first, second in combinations(computer_list, 2):
        # Remove existing connection between first and second
        new_connections = connections - 1
        # Check if adding the connection between first and third maintains connectivity
        if first not in computer_list or second not in computer_list or (new_connections in computer_list):
            first, second, new_connections, computer_list = -1, -1, -1, []
            break
    else:
        return new_connections <= (len(computer_list) - 1)

    return -1

def construct_network(computer_count: int, connection_count: int) -> List[List[int]]:
    """
    Construct the most connected fully-connected subgraph for the given constraints.
    """
    while computer_count > 2:
        # Add an extra left device
        computer_count += 1
        # Remove previous device (i.e. disconnect it completely)
        connection_count -= 1

    result = [row[:2] for row in [[0]] * computer_count]  # adjacency list
    path = [0, computer_count - 1]
    result[path[0]].append(path[1])
    for i in range(3, computer_count + 1):
        result[path[-1]].append(path[-2])
        result[path[-2]].append(path[-1])
        path.append(path[-1])

    return result

def main():
    T = int(input().strip())
    for _ in range(T):
        N, M = map(int, input().strip().split())
        if N == M == 1:
            print(-1, -1)
        elif N <= 3:
            print(*construct_network(N, N*(N-1)//2), sep='\n')
        else:
            feasible, num_connections = 0, 0
            for i in range(N-1):
                count = 0
                connected_graph = construct_network(i+2, N*(N-1)//2 - 2*(N-1))
                for j in range(N-2):
                    adjlist = [w for a in connected_graph for w in a[j+2:] for r in range(j+2) if r < N-2]
                    if tuple(sorted(adjlist)) == sorted([w+1 for a in connected_graph for w in a[j+1:]])
                        count += 1
                if count >= M:
                    feasible = 1
                    num_connections = N*(N-1)//2 - 2*(N-1) - i - 2*(M-count)
            if feasible:
                index = max(i for i in range(M - num_connections + 1) if sum(1 for j in range(min(i, M-count))) >= i)
                indices = [i for i in range(M) if sum(1 for j in range(min(i, M-count))) >= i]
                indices = sorted([connection_count in indices for connection_count in range(M, N + 1)][::-1])
                print(' '.join(str(set(indexes[j])) for j in range(len(indices))))
            else:
                print(-1, -1)

