    southw = [[False] * (sum_of_sequence // 2) for i in range(number_of_cards)]
    eastw = [[False] * (sum_of_sequence // 2) for i in range(number_of_cards)]
    westw = [[False] * (sum_of_sequence // 2) for i in range(number_of_cards)]

