def compute_niceness(a, missing, mod):
    n = len(a)
    total_lcm = 1
    lcm = 1
    for x in a:
        if x != -1:
            lcm = lcm * x // gcd(lcm, x) % mod
        total_lcm = (total_lcm * x) % mod
    total_gcd = (total_lcm - 1) * total_lcm // 2 % mod
    return (total_gcd - missing // 2 + mod) % mod

