                min_cost += costs[i] if i < N % 2 else costs[i] + costs[N // 2 + i]
            if N % 2 == 0:
                min_cost += costs[N // 2] if N % 2 == 0 else costs[N // 2]
                min_cost += costs[N // 2 - 1] if N % 2 == 0 else costs[N // 2 - 1]
    return [i for i in range(N // 2) if min_cost / 2 <= i and i <= N // 2 - 1]

