from collections import Counter

def count_pairs(n, w, positions, velocities):
    position_count = Counter(positions)
    velocity_count = Counter(velocities)

    valid_pairs = 0
    for pos1 in position_count:
        for pos2 in position_count:
            if pos1 <= pos2:
                continue
            for vel1 in velocity_count:
                for vel2 in velocity_count:
                    total_distance = abs(pos1 - pos2)
                    max_velocity = w / max(1, abs(pos1 + vel1 + vel2) + w)
                    if total_distance <= max_velocity:
                        valid_pairs += 1
                        if pos1 > pos2:
                            break
                        if vel1 > 0:
                            break
                        if vel2 > 0:
                            break

    return valid_pairs

