import math

def find_min_cost(N, M, roads):
    subset_size = N // 2
    edges = [math.inf] * M

    for i in range(M):
        a, b, cost = roads[i]
        if a < b:
            a, b = b, a
        if b >= subset_size:
            edges[i] = cost

    for i in range(subset_size, N):
        for j in range(i + 1, N + 1):
            a, b = (i, j) if i < j else (j, i)
            edges[i], edges[j] = edges[j], edges[i]
            for k in range(i + 1, j):
                cost = sum(roads[math.bisect_left(roads, (a, b))] + roads[math.bisect_right(roads, (a, b))] - cost for _ in range(math.dist(a, b))) - edges[k]
                edges[k] = min(edges[k], cost)
            edges[i], edges[j] = (edges[j], edges[i])

    min_cost = min(edges)
    return min_cost
