        row, col, time = map(int, input().split())
        scaygers.append((row - 1, col - 1, time))

    return n, m, males, females, grid, scaygerboss_row - 1, scaygerboss_col - 1, scaygerboss_time, scaygers

def find_solution(grid, scaygerboss_row, scaygerboss_col, scaygerboss_time, scaygers):
    n, m, males, females, _, _, _, _, _ = scaygerboss_row, scaygerboss_col, scaygerboss_time, scaygers

    visited = [[False] * m for _ in range(n)]
    time_steps = [-1]

    def bfs(start_row, start_col, start_time):
        queue = [(start_time, start_row, start_col, -1)]
        visited[start_row][start_col] = True
        next_time = start_time

        while queue:
            row, col, time, prev_time = queue.pop(0)
            if (row, col) == (start_row, start_col) and time > time_steps[-1]:
                time_steps.append(time)
                prev_time = 0

            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                new_row, new_col = row + dx, col + dy
                if 0 <= new_row < n and 0 <= new_col < m and not visited[new_row][new_col]:
                    new_time = time
                    if is_look_erable(grid, new_row, new_col):
                        new_time = prev_time
                        next_time = max(next_time, new_time)
                    visited[new_row][new_col] = True
                    queue.append((new_time, new_row, new_col, new_time))

        return next_time

    def is_look_erable(row, col):
        count_same_type = sum(grid[r][c] == '.' for r in range(n) for c in range(m))
        return count_same_type in {males + females, males, females}

    time = 0

    for row, col, time in scaygers:
        dist = bfs(row, col, time)
        if dist == -1:
            return -1

    return time

def main():
    n, m, males, females, grid, scaygerboss_row, scaygerboss_col, scaygerboss_time, scaygers = read_input()
    result = find_solution(grid, scaygerboss_row, scaygerboss_col, scaygerboss_time, scaygers)
    print(result)

