    for i in range(1, n + 1):
        result = (result * i) % MOD
    return result

def inverse(n):
    return pow(n, MOD - 2, MOD)

def count_subset_sums(n, m):
    numberOfSet = (1 << n) - 1
    return (factorial(numberOfSet) * inverse(factorial(numberOfSet - m))) % MOD

for _ in range(int(input())):
    n, m = map(int, input().split())
    subsets = 0
    for _ in range(n):
        x, y = map(int, input().split())
        subsets = (subsets + count_subset_sums(min(x, y) - 1, max(x, y) + 1)) % MOD
    print(subsets)
