def make_array_grandiose(a):
    n = len(a)

    def is_grandiose(seq):
        for i in range(2, n):
            if seq[i-1] < seq[i] < seq[(i-1)//2] or seq[i-1] > seq[i] > seq[(i-1)//2]:
                return False
        return True

    if is_grandiose(sorted(a)):
        return 0
    swaps = 0

    i = 1
    while i < len(a) and a[i] > a[len(a) // 2]:
        i += 1
    if i == len(a) or a[i] < a[(len(a) - i)//2]:
        i = 0

    while i < len(a) and a[i] > a[len(a) // 2]:
        i += 1
    if i == len(a):
        return -1
    swaps += int(i == len(a) - 1)
    if a[i] < a[(len(a) - i)//2 - 1]:
        swaps += 1

    while i < len(a) and a[i] < a[len(a) // 2]:
        i += 1
    if i == len(a):
        return -1
    swaps += int(i == len(a) - 1)
    if a[i] > a[(len(a) - i)//2 - 1]:
        swaps += 1

    return swaps

T = int(input())
for _ in range(T):
    n = int(input())
    a = list(map(int, input().split()))
    print(make_array_grandiose(a))
