# Function to create a three-dimensional array for the cube
def create_cube(n):
    return [
        [ [i * n*n + j*n + k + 1 for j in range(n) ] for i in range(n) ]
        for k in range(n)
    ]

cube = create_cube(n)

# Fill the diagonals with consecutive numbers to meet the conditions
for i in range(n):
    for j in range(n):
        for k in range(n):
            if i == j == k:
                cube[i][j][k] = cube[i][j][k-1] + n*n + 1
            if i + j + k == n*n*n - 1:
                cube[i][j][k] = cube[i][j][k-1] - n*n + 1


for layer in cube:
    for row in layer:
        row.sort()
    print(' '.join(map(str, layer)))

